/bin/bash -lc "python3 -c \"
import pandas as pd, re
fe = pd.read_excel('national_programme_ledger.xlsx', sheet_name='Field Expenses', header=4)
sal = pd.read_excel('national_programme_ledger.xlsx', sheet_name='Salary Register', header=5)
lookup = pd.read_excel('national_programme_ledger.xlsx', sheet_name='Cost Centre Lookup', header=3)

def norm(s):
    if pd.isna(s): return ''
    return str(s).strip().lower()

def parse_amount(v):
    if pd.isna(v): return 0
    if isinstance(v, (int,float)): return float(v)
    s = str(v).replace('₹','').replace(',','').strip()
    # remove any non-digit
    m = re.search(r'[0-9]+', s)
    # Actually extract all digits
    digits = re.sub(r'["'^0-9]'"','', s)
    if digits:
        return float(digits)
    return 0

# build lookup map
lookup_map = {}
for _, r in lookup.iterrows():
    code_norm = norm(r['Cost Centre Code'])
    lookup_map[code_norm] = {
        'Programme': str(r['Programme']).strip(),
        'State': str(r['State']).strip()
    }

total = 0
# Field Expenses
for _, r in fe.iterrows():
    status = norm(r['Posting Status'])
    if status "'!= '"'posted':
        continue
    cc = norm(r['Cost Centre'])
    if cc not in lookup_map:
        continue
    prog = lookup_map[cc]['Programme']
    state = lookup_map[cc]['State']
    if prog == 'Maternal and Child Health' and state == 'Odisha':
        total += parse_amount(r['Amount (INR)'])

# Salary
for _, r in sal.iterrows():
    status = norm(r['Payroll Status'])
    if status "'!= '"'paid':
        continue
    cc = norm(r['Cost Centre'])
    if cc not in lookup_map:
        continue
    prog = lookup_map[cc]['Programme']
    state = lookup_map[cc]['State']
    if prog == 'Maternal and Child Health' and state == 'Odisha':
        total += parse_amount(r['Gross Salary (INR)'])

print(total)
\"
"
